import React, { useEffect, useState, useRef } from "react";
import html2canvas from "html2canvas";
import "./Main.css";

function importAll(r) {
  return r.keys().map(r);
}
const photos = importAll(require.context("./photos", false, /\.(png|jpe?g)$/));

const compliments = [
  "Ты сегодня невероятная..", "Каждый день с тобой — праздник..", "Ты молодец..",
  "Твоя энергия заставляет улыбаться..", "Ты умеешь делать сложное простым..",
  "С тобой хочется творить..", "Ты особенная, такой больше нет..",
  "Твоя улыбка освещает всё вокруг..", "Ты вдохновляешь своим примером..",
  "Каждое твое слово согревает..", "Ты делаешь мир лучше просто своим существованием..",
  "С тобой хочется быть рядом всегда..", "Ты уникальна и это потрясающе..",
  "Твои идеи всегда яркие и свежие..", "Ты смелая и решительная..",
  "Твоя доброта — редкость в этом мире..", "Ты умеешь радоваться простым вещам..",
  "С тобой легко и приятно общаться..", "Ты настоящий источник вдохновения..",
  "Твоя энергия заряжает позитивом..", "Ты талантлива во всём, за что берешься.."
];

const Main = () => {
  const [current, setCurrent] = useState(0);
  const [displayedMessage, setDisplayedMessage] = useState("");
  const [availableMessages, setAvailableMessages] = useState([...compliments]);
  const [typing, setTyping] = useState(false);
  const photoRef = useRef(null);

  const showRandomMessage = () => {
    let messages = availableMessages.length > 0 ? availableMessages : [...compliments];
    const index = Math.floor(Math.random() * messages.length);
    const msg = messages[index];
    const newAvailable = messages.filter((_, i) => i !== index);
    setAvailableMessages(newAvailable);
    if (!msg) return;

    setDisplayedMessage("");
    setTyping(true);

    const words = msg.split(" ");
    let wordIndex = 0;
    let currentText = "";

    const typeWord = () => {
      if (wordIndex >= words.length) {
        setTyping(false);
        return;
      }
      const word = words[wordIndex];
      let charIndex = 0;
      const typeChar = () => {
        currentText += word[charIndex];
        setDisplayedMessage(currentText);
        charIndex++;
        if (charIndex < word.length) {
          setTimeout(typeChar, 30 + Math.random() * 50);
        } else {
          currentText += " ";
          wordIndex++;
          setTimeout(typeWord, 150 + Math.random() * 200);
        }
      };
      typeChar();
    };
    typeWord();
  };

  useEffect(() => {
    if (window.Telegram && window.Telegram.WebApp) {
      const tg = window.Telegram.WebApp;
      tg.ready();
      tg.MainButton.setText("🚀 Поделиться в чате");

      tg.MainButton.onClick(async () => {
        if (!photoRef.current) return;

        // создаём скриншот блока
        const canvas = await html2canvas(photoRef.current, { scale: 3, useCORS: true });
        const dataURL = canvas.toDataURL("image/png");

        // отправляем данные боту
        tg.sendData(JSON.stringify({
          message: displayedMessage,
          image: dataURL
        }));

        // вызываем официальный репост Telegram с предпросмотром
        if (tg.showPopup) {
          tg.showPopup({
            title: "Предпросмотр сообщения",
            message: displayedMessage,
            photo: dataURL,
            description: "Мини-приложение предлагает вам отправить это сообщение в выбранный вами чат."
          });
        }
      });
    }
  }, [displayedMessage]);

  useEffect(() => {
    if (window.Telegram && window.Telegram.WebApp) {
      const tg = window.Telegram.WebApp;
      if (typing || displayedMessage.trim() === "") tg.MainButton.hide();
      else tg.MainButton.show();
    }
  }, [typing, displayedMessage]);

  return (
    <div className="app" style={{ userSelect: "none" }}>
      <div className="photo-container" ref={photoRef}>
        <img
          src={photos[current]}
          alt="Мы"
          className="photo"
          onClick={() => {
            setCurrent((prev) => (prev + 1) % photos.length);
            showRandomMessage();
          }}
          style={{ pointerEvents: typing ? "none" : "auto" }}
        />
        <div className="text-container">
          <p className={`text ${typing ? "show-message" : ""}`}>
            {displayedMessage}
          </p>
        </div>
      </div>
    </div>
  );
};

export default Main;
